/* Fano Properties — team app + AI (one Cloudflare Worker) — v19 · Fano Properties public property site · tenant app at /tenant with email invites · Promotions · one download link /get · privacy page · client proposals · Ads Center
 * GET  /...        -> the team app files (sign-in, leads, customers, agents, AI Studio...)
 * GET  /portal, /tenant -> tenant app: unit, contract, payments, cheques, requests, offers (invite only)
 * GET  /homes      -> Fano Properties, the public property site (also homes.fanoproperties.workers.dev via the "homes" Worker)
 * GET  /get        -> one download page for all three apps;  GET /privacy -> privacy policy
 * GET|POST /api/promos -> Promotions (owners, super admin, Amy, Umer);  POST /api/tenant/invite -> e-mail a tenant their login
 * GET  /symphony   -> The Symphony by Imtiaz landing page
 * POST /api/meta-lead -> Facebook & Instagram lead ads webhook -> new lead (Secrets META_VERIFY_TOKEN, META_APP_SECRET, META_PAGE_TOKEN)
 * POST /api/web-sync  -> admins: pull listings from fanoproperties.com into Projects now (also runs every 30 min)
 * GET  /install   -> "install the team app" page (share this link with the team)
 * GET  /p, /p/{slug} -> property landing pages (published from Projects -> Landing page in the app)
 * POST /api/lead   -> website enquiry -> new lead in the app's Lead inbox (keeps the Google Ads click ID)
 * POST /api/google-lead -> Google Ads lead-form webhook -> new lead (needs Secret GOOGLE_LEAD_KEY, the same key as in Google Ads)
 * GET  /pfile?p=   -> private ID documents (signed-in user's token; Firebase storage rules decide)
 * GET  /cfile?p=   -> tenant files: contracts, Ejari, receipts (tenant's or staff token; storage rules decide)
 * GET  /img?u=     -> photo pass-through so the photo/video editor can edit website & storage photos
 * POST /api/ai     -> AI endpoint (needs Secret ANTHROPIC_API_KEY in Settings -> Variables and Secrets)
 */

const PROJECT_ID = "fano-properties";
const OWNER_EMAILS = ["marketing@fanoproperties.com", "tamar.buadze@fanoproperties.com"];
const ALLOWED_ORIGINS = ["https://app.fanoproperties.com", "https://app.fanoproperties.workers.dev", "https://fano-ai.fanoproperties.workers.dev", "https://fano-ai.marketing-a98.workers.dev"];
const MODELS = { quick: "claude-haiku-5-5", default: "claude-sonnet-5-5", complex: "claude-opus-5-5" };
const MAX_TOKENS = 4096;

let jwksCache = { keys: null, at: 0 };

function cors(origin) {
  const h = { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" };
  if (ALLOWED_ORIGINS.includes(origin)) {
    h["Access-Control-Allow-Origin"] = origin;
    h["Vary"] = "Origin";
    h["Access-Control-Allow-Headers"] = "Content-Type, Authorization";
    h["Access-Control-Allow-Methods"] = "POST, OPTIONS";
  }
  return h;
}
const out = (status, body, origin) => new Response(JSON.stringify(body), { status, headers: cors(origin) });
const b64urlToBytes = s => { s = s.replace(/-/g, "+").replace(/_/g, "/"); while (s.length % 4) s += "="; const bin = atob(s); return Uint8Array.from(bin, c => c.charCodeAt(0)); };
const b64urlJSON = s => JSON.parse(new TextDecoder().decode(b64urlToBytes(s)));

async function googleKeys(force) {
  if (!force && jwksCache.keys && Date.now() - jwksCache.at < 3600e3) return jwksCache.keys;
  const r = await fetch("https://www.googleapis.com/service_accounts/v1/jwk/securetoken@system.gserviceaccount.com");
  if (!r.ok) throw new Error("certs");
  jwksCache = { keys: (await r.json()).keys || [], at: Date.now() };
  return jwksCache.keys;
}

async function verifyToken(token) {
  const parts = String(token || "").split(".");
  if (parts.length !== 3) return null;
  const [h, p, s] = parts;
  let header, payload;
  try { header = b64urlJSON(h); payload = b64urlJSON(p); } catch (e) { return null; }
  if (header.alg !== "RS256" || !header.kid) return null;
  let jwk = (await googleKeys(false)).find(k => k.kid === header.kid);
  if (!jwk) jwk = (await googleKeys(true)).find(k => k.kid === header.kid);
  if (!jwk) return null;
  const key = await crypto.subtle.importKey("jwk", jwk, { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" }, false, ["verify"]);
  const ok = await crypto.subtle.verify("RSASSA-PKCS1-v1_5", key, b64urlToBytes(s), new TextEncoder().encode(h + "." + p));
  const now = Math.floor(Date.now() / 1000);
  if (!ok || payload.aud !== PROJECT_ID || payload.iss !== "https://securetoken.google.com/" + PROJECT_ID
      || (payload.exp || 0) < now - 60 || (payload.iat || now + 999) > now + 300 || !payload.sub) return null;
  return payload;
}

async function isMember(email, token) {
  if (OWNER_EMAILS.includes(email)) return true;
  const url = `https://firestore.googleapis.com/v1/projects/${PROJECT_ID}/databases/(default)/documents/members/${encodeURIComponent(email)}`;
  const r = await fetch(url, { headers: { Authorization: "Bearer " + token } });
  if (!r.ok) return false;
  const doc = await r.json();
  return doc && doc.fields && doc.fields.active && doc.fields.active.booleanValue === true;
}

async function handleAI(request, env) {
  {
    const origin = request.headers.get("Origin") || "";
    if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: cors(origin) });
    if (request.method !== "POST") return out(405, { error: "POST only" }, origin);
    if (!env.ANTHROPIC_API_KEY) return out(503, { error: "AI is not set up yet (ANTHROPIC_API_KEY missing)." }, origin);

    let body;
    try { body = await request.json(); } catch (e) { return out(400, { error: "Bad request" }, origin); }
    const auth = request.headers.get("Authorization") || "";
    const token = auth.startsWith("Bearer ") ? auth.slice(7).trim() : String(body.idToken || "");
    let user;
    try { user = await verifyToken(token); } catch (e) { return out(503, { error: "Could not check sign-in right now" }, origin); }
    if (!user) return out(401, { error: "Sign-in expired — reload the app" }, origin);
    if (!user.email || !user.email_verified) return out(403, { error: "Email not confirmed" }, origin);
    const email = String(user.email).toLowerCase();
    if (!(await isMember(email, token))) return out(403, { error: "Not on the Fano team list" }, origin);

    // Build the Claude request
    const messages = [];
    for (const m of Array.isArray(body.messages) ? body.messages : []) {
      const role = m.role === "assistant" ? "assistant" : "user";
      const text = String(m.content || "").trim();
      if (!text) continue;
      const last = messages[messages.length - 1];
      if (last && last.role === role) last.content[0].text += "\n\n" + text;
      else messages.push({ role, content: [{ type: "text", text }] });
    }
    if (!messages.length || messages[0].role !== "user" || messages[messages.length - 1].role !== "user")
      return out(400, { error: "Conversation must start and end with the user" }, origin);
    const lastMsg = messages[messages.length - 1];
    const imgs = (Array.isArray(body.images) ? body.images : []).slice(0, 5)
      .filter(i => ["image/jpeg", "image/png", "image/webp", "image/gif"].includes(i.media_type) && i.data)
      .map(i => ({ type: "image", source: { type: "base64", media_type: i.media_type, data: i.data } }));
    if (imgs.length) lastMsg.content = imgs.concat(lastMsg.content);
    if (body.json) lastMsg.content[lastMsg.content.length - 1].text += "\n\nReply with only valid JSON — no other text.";
    const tier = ["quick", "complex"].includes(body.tier) ? body.tier : "default";

    const r = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "content-type": "application/json", "anthropic-version": "2023-06-01", "x-api-key": env.ANTHROPIC_API_KEY },
      body: JSON.stringify({ model: MODELS[tier], max_tokens: MAX_TOKENS, messages })
    });
    if (r.status === 429) return out(429, { error: "AI is busy — try again in a minute" }, origin);
    const res = await r.json().catch(() => null);
    if (!r.ok || !res) { console.log("Fano AI error", r.status, JSON.stringify(res).slice(0, 500)); return out(502, { error: "The AI service returned an error" }, origin); }
    const text = (res.content || []).filter(b => b.type === "text").map(b => b.text).join("");
    return out(200, { text, truncated: res.stop_reason === "max_tokens" }, origin);
  }
}

