const LP_ICONS = ['<path d="M3 21h18M5 21V10l4-3v14M9 21V4l6 3v14M15 21v-9l4 2v7"/>', '<path d="M12 22V12M12 12c0-4 3-7 8-8-1 5-4 8-8 8zM12 15c0-3-2.5-5.5-7-6 .5 4 3 6 7 6z"/>', '<path d="M4 21V9l8-6 8 6v12M9 21v-7h6v7M2 21h20"/>', '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>', '<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>', '<path d="M12 3l2.6 5.3 5.9.9-4.3 4.1 1 5.8L12 16.4 6.8 19.1l1-5.8L3.5 9.2l5.9-.9z"/>'];
