  const auth = await acAuth(request);
  if (!auth.ok) return jsonRes(auth.status, { error: auth.error });
  let body = {};
  if (request.method === "POST") { const raw = await request.text(); if (raw.length > 3e6) return jsonRes(413, { error: "too_big" }); try { body = JSON.parse(raw || "{}"); } catch (e) { return jsonRes(400, { error: "bad_json" }); } }
