const AC_GEO = { "2784": "UAE", "2682": "Saudi Arabia", "2634": "Qatar", "2414": "Kuwait", "2048": "Bahrain", "2512": "Oman", "2400": "Jordan", "2422": "Lebanon", "2368": "Iraq", "2818": "Egypt", "2356": "India", "2586": "Pakistan", "2826": "United Kingdom", "2840": "United States", "2643": "Russia", "2276": "Germany", "2250": "France", "2156": "China", "2608": "Philippines" };
