  if (rows.length < 2) return { rows: [] };
  const head = rows[0].map(h => h.trim().toLowerCase());
  const col = (...names) => { for (const nm of names) { const i = head.findIndex(h => h === nm); if (i >= 0) return i; } for (const nm of names) { const i = head.findIndex(h => h.includes(nm)); if (i >= 0) return i; } return -1; };
  const num = v => { const x = Number(String(v || "").replace(/[^0-9.\-]/g, "")); return Number.isFinite(x) ? x : 0; };
  const c = { name: col("campaign name", "campaign"), spend: col("amount spent (aed)", "amount spent", "spend", "total spend", "cost"), impr: col("impressions"), reach: col("reach"), freq: col("frequency"), clicks: col("link clicks", "url clicks", "clicks"), results: col("leads", "results", "conversions"), messages: col("messaging conversations started", "conversations"), eng: col("engagements", "post engagements"), start: col("reporting starts", "time period", "date", "start"), end: col("reporting ends", "end") };
