async function acLeadStats(env) {
  if (!hasFb(env)) return null;
  const tok = await saToken(env);
  const leads = await fsListAll(tok, "leads");
  const since = Date.now() - 30 * 864e5;
  const by = {};
  let nonBuyers = 0;
  for (const l of leads) {
    if (Number(l.createdAt) < since) continue;
    const src = String(l.source || "Other");
    const b = by[src] = by[src] || { leads: 0, qualified: 0, won: 0, nonBuyer: 0, adClick: 0 };
    b.leads++;
    if (["Viewing", "Negotiation", "Won"].includes(l.status)) b.qualified++;
    if (l.status === "Won") b.won++;
    if (l.nonBuyer) { b.nonBuyer++; nonBuyers++; }
    if (l.gclid || l.gbraid || l.wbraid || /Google Ads click ID/.test(String(l.notes || ""))) b.adClick++;
  }
  return { period: "Last 30 days", bySource: by, nonBuyers };
}
